Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #ui {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            font-family: 'Arial', sans-serif;
            font-weight: bold;
            font-size: 24px;
            color: white;
            text-shadow: 2px 2px 4px #000000;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="ui">RACE IN PROGRESS</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = 50;
        const RESET_Z = -100;
        const LANE_WIDTH = 6;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 8, -20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, -10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 400);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Grass strips
        const grassGeo = new THREE.PlaneGeometry(100, 400);
        const grassMat = new THREE.MeshStandardMaterial({ color: 0x44aa44 });
        const grassLeft = new THREE.Mesh(grassGeo, grassMat);
        grassLeft.rotation.x = -Math.PI / 2;
        grassLeft.position.x = -50;
        grassLeft.position.y = 0.01;
        scene.add(grassLeft);

        const grassRight = grassLeft.clone();
        grassRight.position.x = 50;
        scene.add(grassRight);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(30, 2);
        const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff }); // Checkerboard pattern simulated by white
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, FINISH_LINE_Z);
        scene.add(finishLine);

        // Finish Line Arch
        const archGeo = new THREE.BoxGeometry(32, 1, 2);
        const archMat = new THREE.MeshStandardMaterial({ color: 0xdddddd });
        const arch = new THREE.Mesh(archGeo, archMat);
        arch.position.set(0, 5, FINISH_LINE_Z);
        scene.add(arch);

        const pillarGeo = new THREE.BoxGeometry(2, 10, 2);
        const pillarLeft = new THREE.Mesh(pillarGeo, archMat);
        pillarLeft.position.set(-15, 0, FINISH_LINE_Z);
        scene.add(pillarLeft);
        const pillarRight = new THREE.Mesh(pillarGeo, archMat);
        pillarRight.position.set(15, 0, FINISH_LINE_Z);
        scene.add(pillarRight);

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 0.8, 4.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.8;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Dark glass
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.5;
            cabin.position.z = -0.2;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1.1, z: 1.5 },
                { x: 1.1, z: 1.5 },
                { x: -1.1, z: -1.5 },
                { x: 1.1, z: -1.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2, 0.1, 0.8);
            const spoilerMat = new THREE.MeshStandardMaterial({ color: color });
            const spoiler = new THREE.Mesh(spoilerGeo, spoilerMat);
            spoiler.position.set(0, 1.6, 2);
            carGroup.add(spoiler);

            const spoilerStandGeo = new THREE.BoxGeometry(0.2, 0.4, 0.2);
            const stand1 = new THREE.Mesh(spoilerStandGeo, spoilerMat);
            stand1.position.set(-0.8, 1.4, 2);
            carGroup.add(stand1);
            const stand2 = new THREE.Mesh(spoilerStandGeo, spoilerMat);
            stand2.position.set(0.8, 1.4, 2);
            carGroup.add(stand2);

            return carGroup;
        }

        const blueCar = createCar(0x0000ff);
        const redCar = createCar(0xff0000);
        scene.add(blueCar);
        scene.add(redCar);

        // --- Animation Logic ---
        let raceTime = 0;
        const uiElement = document.getElementById('ui');

        function animate() {
            requestAnimationFrame(animate);

            // Race Loop Logic
            const raceDuration = 8; // seconds per race
            const loopDuration = 10; // seconds total (including reset)
            const resetTime = loopDuration - raceDuration;

            raceTime += 0.016; // approx 60fps step
            if (raceTime > loopDuration) raceTime = 0;

            let currentRaceTime = raceTime;
            let isResetting = false;

            if (raceTime > raceDuration) {
                isResetting = true;
                currentRaceTime = 0;
                uiElement.innerText = "RESETTING...";
                uiElement.style.color = "#cccccc";
            } else {
                uiElement.innerText = "RACE IN PROGRESS";
                uiElement.style.color = "white";
            }

            // Normalize time 0 to 1 for the race duration
            const t = currentRaceTime / raceDuration;

            // --- Movement Logic ---

            // Blue Car: Starts fast, slows down slightly (Linear-ish)
            // We want Blue to lead early.
            let bluePos;
            if (t < 0.5) {
                // Fast start
                bluePos = RESET_Z + (TRACK_LENGTH + 150) * (t * 2.2); 
            } else {
                // Maintains lead but Red catches up
                bluePos = RESET_Z + (TRACK_LENGTH + 150) * (1.1 + (t * 0.9));
            }
            // Clamp to finish line visually
            if (bluePos > FINISH_LINE_Z) bluePos = FINISH_LINE_Z;

            // Red Car: Starts slow, accelerates massively
            // Use ease-in-out cubic or similar for acceleration
            let redPos;
            // Start behind blue
            const startOffset = 10; 
            // Red needs to cross finish line at t=1

            // Custom acceleration curve
            // 0 -> 1
            const accel = t * t * t; 

            // Red starts at RESET_Z + startOffset
            // Red ends at FINISH_LINE_Z

            // Let's make Red start at same Z, but move slower initially
            // Blue distance = 350 units approx
            // Red distance = 350 units approx

            // Blue Position Calculation refined:
            // Blue moves 0 to 350 over 0 to 1
            // Blue is linear: z = -100 + 350 * t
            const blueZ = RESET_Z + 350 * t;

            // Red Position Calculation:
            // Red moves 0 to 350 over 0 to 1
            // Red is cubic (slow start, fast end): z = -100 + 350 * (t^3)
            // To make Red win, Red's curve needs to be steeper at the end.
            // Let's use a power of 2.5 for Red to catch up.
            // Actually, let's just define positions manually for better control.

            // Blue: Linear
            const finalBlueZ = RESET_Z + 350 * t;

            // Red: Starts slightly behind, accelerates to overtake
            // At t=0.5, Blue is at -25. Red should be at -30.
            // At t=1.0, Red is at 50 (Finish), Blue is at 50.
            // Wait, Red wins. So Red reaches 50 at t=0.95?

            // Let's try this:
            // Blue reaches finish at t = 0.9
            // Red reaches finish at t = 1.0
            // But Red overtakes Blue.

            // Blue Curve: Fast start, steady.
            // Red Curve: Slow start, massive acceleration.

            // Let's use simple interpolation functions.
            // Blue: Linear
            const blueDist = 350 * t;

            // Red: Cubic ease out (starts slow, ends fast)
            // To overtake, Red needs to cover more distance than Blue in the second half.
            // Red starts 10 units behind.
            const redDist = 350 * Math.pow(t, 2.2) - 10; 

            // Adjust so Red wins (crosses finish line first)
            // If we want Red to win, Red's distance should be > Blue's distance at end.
            // Let's shift Red's curve.

            // Let's simply animate Z positions.
            // Start Z: -100. Finish Z: 50. Total dist: 150.

            // Blue: Linear
            const bZ = RESET_Z + 150 * t;

            // Red: Starts slow, accelerates.
            // We want Red to be behind Blue at t=0.5, and ahead at t=0.8
            // Red Z = -100 + 150 * (t^2.5) ... this is too slow.

            // Let's use a custom function.
            // Red starts at -100.
            // At t=0.5, Red is at -60. Blue is at -25. (Blue leads)
            // At t=1.0, Red is at 50. Blue is at 50.

            // Let's make Red win clearly.
            // Red finishes at t=0.95.
            // Blue finishes at t=1.0.

            // Blue Z
            let finalBluePos = RESET_Z + 150 * t;

            // Red Z
            // Use a power curve. 150 * (t^2) is slow start.
            // To overtake, we need a steeper curve.
            // Let's try: 150 * (t^1.8) but shifted?

            // Let's just use two phases for Red.
            // Phase 1 (0-0.6): Slow.
            // Phase 2 (0.6-1.0): Fast.

            let finalRedPos = RESET_Z;
            if (t < 0.6) {
                // Moves 0 to 60% of distance, but only covers 40% of track
                finalRedPos = RESET_Z + 150 * (t / 0.6) * 0.4;
            } else {
                // Moves 60% to 100% of time, covers remaining 60% of track + wins
                // Actually let's just say Red finishes at t=0.95
                const raceT = t / 0.95; // Normalize to finish at 0.95
                // Cubic ease in
                finalRedPos = RESET_Z + 150 * (raceT * raceT * raceT);
            }

            // Clamp positions
            if (finalBluePos > FINISH_LINE_Z) finalBluePos = FINISH_LINE_Z;
            if (finalRedPos > FINISH_LINE_Z) finalRedPos = FINISH_LINE_Z;

            // Apply positions
            blueCar.position.z = finalBluePos;
            blueCar.position.x = -LANE_WIDTH / 2;

            redCar.position.z = finalRedPos;
            redCar.position.x = LANE_WIDTH / 2;

            // Wheel rotation
            const wheelSpeed = 0.5;
            blueCar.children.forEach(c => {
                if(c.geometry.type === 'CylinderGeometry') c.rotation.x += wheelSpeed;
            });
            redCar.children.forEach(c => {
                if(c.geometry.type === 'CylinderGeometry') c.rotation.x += wheelSpeed;
            });

            // --- Camera Logic ---
            // Camera follows the midpoint of the two cars, but stays behind them
            const midZ = (finalBluePos + finalRedPos) / 2;

            // Target camera position
            const camTargetZ = midZ - 25; // 25 units behind the midpoint
            const camTargetY = 8;
            const camTargetX = 0;

            // Smooth camera movement
            camera.position.z += (camTargetZ - camera.position.z) * 0.1;
            camera.position.y += (camTargetY - camera.position.y) * 0.1;
            camera.position.x += (camTargetX - camera.position.x) * 0.1;

            // Look at the midpoint slightly ahead
            camera.lookAt(0, 0, midZ + 10);

            // --- Reset Logic ---
            if (isResetting) {
                // Fade out cars or just snap them back?
                // Let's snap them back smoothly
                const resetProgress = (raceTime - raceDuration) / resetTime;

                // Move cars back to start
                blueCar.position.z = THREE.MathUtils.lerp(FINISH_LINE_Z, RESET_Z, resetProgress);
                redCar.position.z = THREE.MathUtils.lerp(FINISH_LINE_Z, RESET_Z, resetProgress);

                // Move camera back
                camera.position.z = THREE.MathUtils.lerp(FINISH_LINE_Z - 25, RESET_Z - 25, resetProgress);
            }

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
